+  <a class="skip-link" href="#maincontent">Skip to main content</a>
+  <main id="maincontent">
+    <section class="hero" aria-labelledby="page-title">
+      <h1 id="page-title">Contact support</h1>
+      <p>Send us your details and we’ll get back to you as soon as possible.</p>
+    </section>
+
+    <section class="card" aria-labelledby="form-title">
+      <h2 id="form-title">Request help</h2>
+      <p id="form-status" class="status" aria-live="polite" hidden></p>
+
+      <form id="support-form" novalidate>
+        <div class="form-field">
+          <label for="full-name">Full name <span class="required-indicator" aria-hidden="true">*</span></label>
+          <input
+            id="full-name"
+            name="full-name"
+            type="text"
+            autocomplete="name"
+            required
+            aria-describedby="full-name-error"
+          >
+          <p id="full-name-error" class="error" hidden></p>
+        </div>
+
+        <div class="form-field">
+          <label for="email-address">Email address <span class="required-indicator" aria-hidden="true">*</span></label>
+          <input
+            id="email-address"
+            name="email-address"
+            type="email"
+            autocomplete="email"
+            required
+            aria-describedby="email-address-error"
+          >
+          <p id="email-address-error" class="error" hidden></p>
+        </div>
+
+        <div class="form-field">
+          <label for="phone-number">Phone number</label>
+          <input
+            id="phone-number"
+            name="phone-number"
+            type="tel"
+            autocomplete="tel"
+            inputmode="tel"
+            aria-describedby="phone-number-hint phone-number-error"
+          >
+          <p id="phone-number-hint" class="hint">Optional. Use a format like +1 555 123 4567 or 555-123-4567.</p>
+          <p id="phone-number-error" class="error" hidden></p>
+        </div>
+
+        <div class="actions">
+          <button type="submit">Send message</button>
+        </div>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('support-form');
+    const statusMessage = document.getElementById('form-status');
+    const fields = {
+      name: {
+        input: document.getElementById('full-name'),
+        error: document.getElementById('full-name-error'),
+        validate(value) {
+          if (!value.trim()) {
+            return 'Error: Full name is required.';
+          }
+          return '';
+        }
+      },
+      email: {
+        input: document.getElementById('email-address'),
+        error: document.getElementById('email-address-error'),
+        validate(value) {
+          if (!value.trim()) {
+            return 'Error: Email address is required.';
+          }
+
+          if (!fields.email.input.validity.valid) {
+            return 'Error: Enter a valid email address, like name@example.com.';
+          }
+
+          return '';
+        }
+      },
+      phone: {
+        input: document.getElementById('phone-number'),
+        error: document.getElementById('phone-number-error'),
+        validate(value) {
+          const trimmed = value.trim();
+          if (!trimmed) {
+            return '';
+          }
+
+          const allowedCharacters = /^[0-9()+.\-\s]+$/;
+          const digitsOnly = trimmed.replace(/\D/g, '');
