+        return;
+      }
+
+      statusMessage.hidden = false;
+      statusMessage.dataset.state = type;
+      statusMessage.textContent = message;
+    }
+
+    function setError(field, message) {
+      const hasError = Boolean(message);
+      field.input.setAttribute('aria-invalid', hasError ? 'true' : 'false');
+      field.error.hidden = !hasError;
+      field.error.textContent = message;
+    }
+
+    function validateField(field) {
+      const message = field.validate(field.input.value);
+      setError(field, message);
+      return !message;
+    }
+
+    function validateForm() {
+      const validName = validateField(fields.name);
+      const validEmail = validateField(fields.email);
+      const validPhone = validateField(fields.phone);
+      return validName && validEmail && validPhone;
+    }
+
+    function markTouched(field) {
+      field.input.dataset.touched = 'true';
+    }
+
+    Object.values(fields).forEach((field) => {
+      field.input.addEventListener('blur', () => {
+        markTouched(field);
+        validateField(field);
+      });
+
+      field.input.addEventListener('input', () => {
+        if (field.input.dataset.touched === 'true' || state.submitted) {
+          validateField(field);
+        }
+        if (statusMessage.hidden === false) {
+          setStatus('', '');
+        }
+      });
+    });
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+      state.submitted = true;
+
+      const isValid = validateForm();
+
+      if (!isValid) {
+        setStatus('error', 'Please fix the errors in the form.');
+        const firstInvalid = form.querySelector('[aria-invalid="true"]');
+        if (firstInvalid) {
+          firstInvalid.focus();
+        }
+        return;
+      }
+
+      setStatus('success', 'Thanks — your message is ready to send.');
+      form.reset();
+
+      Object.values(fields).forEach((field) => {
+        field.input.removeAttribute('aria-invalid');
+        field.error.hidden = true;
+        field.error.textContent = '';
+        delete field.input.dataset.touched;
+      });
+
+      fields.name.input.focus();
+    });
+  </script>
+</body>
+</html>
