       const message = field.validate(field.input.value);
       setError(field, message);
       return !message;
     }

     function validateForm() {
       const validName = validateField(fields.name);
       const validEmail = validateField(fields.email);
       const validPhone = validateField(fields.phone);
       return validName && validEmail && validPhone;
     }

     function markTouched(field) {
       field.input.dataset.touched = 'true';
     }

     Object.values(fields).forEach((field) => {
       field.input.addEventListener('blur', () => {
         markTouched(field);
         validateField(field);
       });

       field.input.addEventListener('input', () => {
         if (field.input.dataset.touched === 'true' || state.submitted) {
           validateField(field);
         }
         if (statusMessage.hidden === false) {
           setStatus('', '');
         }
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       state.submitted = true;

       const isValid = validateForm();

